U0 Values()
{
  I64 candles=7;
  I64 rows=3;
  F64 length=2.5;
  "Candles: %d\n",candles;
  "Total: %d\n",candles*rows;
  "Length: %.2f\n",length;
}
Values;

U0 Types()
{
  I64 whole=7/2;
  F64 fraction=7.0/2.0;
  "I64 bytes: %d\n",sizeof(I64);
  "U8 bytes: %d\n",sizeof(U8);
  "Integer: %d\n",whole;
  "Fraction: %.1f\n",fraction;
  "Remainder: %d\n",7%2;
}
Types;

U0 Choice()
{
  I64 lamps=3;
  if (lamps>0) {
    "The room has light.\n";
  } else {
    "Light a lamp.\n";
  }
  if (1<=lamps<=7)
    "Between one and seven.\n";
}
Choice;

U0 Steps()
{
  I64 i,total=0;
  for (i=1;i<=7;i++) {
    total+=i;
    "Step %d, total %d\n",i,total;
  }
}
Steps;

I64 Square(I64 n)
{
  return n*n;
}
U0 Greet(U8 *name="friend")
{
  "Peace, %s.\n",name;
}
Greet;
Greet("Terry");
"Square: %d\n",Square(4);

U0 Seeds()
{
  I64 count[4];
  count[0]=2;
  count[1]=3;
  count[2]=5;
  count[3]=7;
  I64 i,total=0;
  for (i=0;i<4;i++) {
    "Bed %d: %d\n",i,count[i];
    total+=count[i];
  }
  "All seeds: %d\n",total;
}
Seeds;

U0 Words()
{
  U8 text[16];
  StrCpy(text,"PEACE");
  "Before: %s\n",text;
  "Length: %d\n",StrLen(text);
  "First: %c\n",text[0];
  text[0]='p';
  "After: %s\n",text;
}
Words;

U0 PointerLesson()
{
  I64 lamp=3;
  I64 *address=&lamp;
  "Before: %d\n",lamp;
  *address=7;
  "After: %d\n",lamp;
}
PointerLesson;

class CLamp
{
  I64 x,y;
  Bool lit;
};
U0 RecordLesson()
{
  CLamp lamp;
  lamp.x=120;
  lamp.y=80;
  lamp.lit=TRUE;
  "Lamp: %d,%d lit=%d\n",
    lamp.x,lamp.y,lamp.lit;
}
RecordLesson;

U0 HeapLesson()
{
  I64 i;
  I64 *values=MAlloc(4*sizeof(I64));
  if (!values)
    return;
  for (i=0;i<4;i++)
    values[i]=i*i;
  "Last: %d\n",values[3];
  Free(values);
  values=NULL;
}
HeapLesson;

U0 SaveNote()
{
  U8 *text="A small work, made with care.\n";
  I64 size=StrLen(text);
  FileWrite("NOTE.TXT",text,size);
  "Requested bytes: %d\n",size;
}
SaveNote;

U0 ReadNote()
{
  I64 size=0,i;
  U8 *text=FileRead("NOTE.TXT",&size);
  if (!text) {
    "Run SAVE.HC first.\n";
    return;
  }
  "Read bytes: %d\n",size;
  for (i=0;i<size;i++)
    "%c",text[i];
  Free(text);
}
ReadNote;

U0 SayHello()
{
  U8 *name=GetStr("Your name: ");
  if (name) {
    "Hello, %s.\n",name;
    Free(name);
  }
}
SayHello;

U0 SixNumbers()
{
  I64 i,value;
  for (i=0;i<6;i++) {
    value=1+RandU32%6;
    "%d\n",value;
  }
}
SixNumbers;

U0 Shapes()
{
  CDC *dc=DCAlias;
  DCFill(dc,WHITE);
  dc->color=BLUE;
  GrRect(dc,40,60,100,60);
  dc->color=RED;
  GrCircle(dc,190,90,30);
  dc->color=GREEN;
  GrLine(dc,40,150,220,150);
  dc->color=BLACK;
  GrPrint(dc,40,180,"Peace");
  GetChar;
  DCFill(dc);
  DCDel(dc);
}
Shapes;

U0 PaletteLesson()
{
  I64 i;
  CDC *dc=DCAlias;
  DCFill(dc,WHITE);
  for (i=0;i<16;i++) {
    dc->color=i;
    GrRect(dc,20+(i%4)*55,
      30+(i/4)*45,45,35);
  }
  GetChar;
  DCFill(dc);
  DCDel(dc);
}
PaletteLesson;

U0 LightDrawing(CTask *task,CDC *dc)
{
  I64 x=task->pix_width/2;
  I64 y=task->pix_height/2;
  dc->color=YELLOW;
  GrCircle(dc,x,y,45);
  dc->color=BLUE;
  GrRect(dc,x-4,y-30,9,60);
  GrRect(dc,x-24,y-15,49,8);
}
U0 LightWindow()
{
  SettingsPush;
  DocClear;
  Fs->draw_it=&LightDrawing;
  GetChar;
  SettingsPop;
}
LightWindow;

I64 glow_x=30;
U0 GlowDraw(CTask *,CDC *dc)
{
  dc->color=YELLOW;
  GrCircle(dc,glow_x,90,12);
}
U0 Glow()
{
  I64 i;
  SettingsPush;
  DocClear;
  Fs->draw_it=&GlowDraw;
  for (i=0;i<60;i++) {
    glow_x=30+i*3;
    Sleep(30);
  }
  SettingsPop;
}
Glow;

I64 pilgrim_x=100;
U0 PilgrimDraw(CTask *,CDC *dc)
{
  dc->color=BLUE;
  GrRect(dc,pilgrim_x,100,12,12);
}
U0 Pilgrim()
{
  I64 key;
  SettingsPush;
  DocClear;
  Fs->draw_it=&PilgrimDraw;
  "A/D: move, Q: finish\n";
  while ((key=GetChar(,FALSE))!='q') {
    if (key=='a') pilgrim_x-=8;
    if (key=='d') pilgrim_x+=8;
    pilgrim_x=ClampI64(pilgrim_x,8,240);
  }
  SettingsPop;
}
Pilgrim;

U0 ThreeTones()
{
  Snd(60);
  Sleep(150);
  Snd;
  Sleep(100);
  Snd(64);
  Sleep(150);
  Snd;
  Sleep(100);
  Snd(67);
  Sleep(300);
  Snd;
}
ThreeTones;

U0 Letter()
{
  "$$FG,BLUE$$A SMALL OFFERING$$FG$$\n";
  "Make something with care.\n";
  "$$UL,1$$Read. Change. Share.$$UL,0$$\n";
}
Letter;

U0 CountSlowly()
{
  I64 i;
  for (i=1;i<=5;i++) {
    "Count %d\n",i;
    Sleep(250);
  }
}
CountSlowly;

#define GARDEN_COUNT 7
I64 garden_lit=0;

U0 GardenDraw(CTask *task,CDC *dc)
{
  I64 i,x,y;
  I64 width=task->pix_width;
  I64 height=task->pix_height;
  dc->color=BLUE;
  GrPrint(dc,16,20,"A SMALL OFFERING");
  GrPrint(dc,16,40,"1-7: lamps   R: reset   Q: leave");
  y=height/2;
  for (i=0;i<GARDEN_COUNT;i++) {
    x=(i+1)*width/(GARDEN_COUNT+1);
    dc->color=LTGRAY;
    GrRect(dc,x-6,y,13,40);
    if (garden_lit & (1<<i))
      dc->color=YELLOW;
    else
      dc->color=DKGRAY;
    GrCircle(dc,x,y-12,9);
    dc->color=BLUE;
    GrPrint(dc,x-4,y+50,"%d",i+1);
  }

  dc->color=BLUE;
  if (garden_lit==127)
    GrPrint(dc,16,height-35,"Peace be with you.");
}

U0 Garden()
{
  I64 key;
  SettingsPush;
  DocClear;
  Fs->draw_it=&GardenDraw;
  while ((key=GetChar(,FALSE))!='q') {
    if ('1'<=key<='7')
      garden_lit^=1<<(key-'1');
    if (key=='r')
      garden_lit=0;
  }
  SettingsPop;
}
Garden;
